import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import { ArrowUpRight, Boxes, Cloud, Code2, Database, Maximize2, Menu, Minimize2, Moon, Network, PanelRight, Plus, Search, Server, ShieldCheck, Sparkles, Sun, Trash2, Workflow, X, ZoomIn, ZoomOut } from 'lucide-react';
