type Page = 'home' | 'services' | 'work' | 'playground' | 'about';
type Theme = 'dark' | 'light';
const MEETING_URL = 'https://calendly.com/snharish85/client-meeting';
const navigate = (page: Page | string) => { window.history.pushState({}, '', page === 'home' ? '/' : `/${page}`); window.dispatchEvent(new PopStateEvent('popstate')); window.scrollTo(0, 0); };
const pageFromPath = (): Page => { const p = window.location.pathname.split('/')[1]; if (p === 'workspace') return 'playground'; return ['services','work','playground','about'].includes(p) ? p as Page : 'home'; };

function Header({theme,onToggleTheme}:{theme:Theme;onToggleTheme:()=>void}) { const [open, setOpen] = useState(false); const links: [string, Page][] = [['Services','services'],['Use cases','work'],['About','about']]; return <header className="header"><button className="logo" onClick={() => navigate('home')}>kloud<span>lab</span><small>.in</small></button><nav className={open ? 'nav open' : 'nav'}>{links.map(([label, page]) => <button key={page} onClick={() => {navigate(page);setOpen(false)}}>{label}</button>)}<button onClick={() => {navigate('playground');setOpen(false)}}>Playground <ArrowUpRight size={14}/></button></nav><button className="mobile-menu" onClick={() => setOpen(!open)} aria-label="Menu">{open ? <X/> : <Menu/>}</button><div className="header-actions"><button type="button" className="theme-toggle" onClick={onToggleTheme} aria-label={`Switch to ${theme==='dark'?'light':'dark'} mode`} title={`Switch to ${theme==='dark'?'light':'dark'} mode`}>{theme==='dark'?<Sun/>:<Moon/>}<span>{theme==='dark'?'Light':'Dark'}</span></button></div></header> }
function Button({ children, onClick, secondary=false }: {children: React.ReactNode; onClick?: () => void; secondary?: boolean}) { return <button className={secondary ? 'button secondary' : 'button'} onClick={onClick}>{children}<ArrowUpRight size={16}/></button> }
function Footer() { return <footer className="footer"><div><button className="logo" onClick={() => navigate('home')}>kloud<span>lab</span><small>.in</small></button><p>Cloud engineering that earns its keep.</p></div><div className="footer-links"><button onClick={() => navigate('services')}>Services</button><button onClick={() => navigate('work')}>Use cases</button><a href={MEETING_URL} target="_blank" rel="noreferrer">Book a meeting <ArrowUpRight size={14}/></a></div><div className="footer-bottom"><span>© 2026 KloudLab Technologies</span><span>Built for the cloud-native few.</span></div></footer> }
function ArchitectureVisual() { return <div className="architecture-visual"><div className="arch-top"><span><i/> KloudLab / architecture</span><span>AWS</span></div><div className="arch-canvas"><div className="arch-node user"><Network/><b>Users</b><small>HTTPS</small></div><div className="connector c1"/><div className="arch-node edge"><Cloud/><b>CloudFront</b><small>Global edge</small></div><div className="connector c2"/><div className="arch-node app"><Server/><b>EC2 + Docker</b><small>Containerized API</small></div><div className="connector c3"/><div className="arch-node data"><Database/><b>DynamoDB</b><small>On-demand</small></div><div className="arch-node security"><ShieldCheck/><b>KMS + SSM</b><small>Encrypted config</small></div></div><div className="arch-status"><span><i/> Live canvas preview</span><strong>Open it in the Playground</strong></div></div> }
function Home() {
  return <><main>
    <section className="hero home-hero wrap"><div className="hero-copy"><div className="eyebrow"><i/> Cloud architecture playground</div><h1>Design the cloud.<br/><em>Then build it.</em></h1><p>Explore AWS, GCP, Azure, Oracle Cloud, Kubernetes, IaC, CI/CD and observability on a live canvas. No account needed.</p><div className="hero-actions"><Button onClick={() => navigate('playground')}>Open the playground</Button><a className="button secondary" href={MEETING_URL} target="_blank" rel="noreferrer">Book a meeting <ArrowUpRight size={16}/></a></div></div><ArchitectureVisual/></section>
    <section className="credential-strip wrap" aria-label="Engineering certifications"><div><ShieldCheck/><span>AWS Professional-certified engineers</span></div><i/><div><Boxes/><span>Kubernetes-certified engineers</span></div></section>
    <section className="home-scope wrap" aria-label="Playground catalog">AWS <i/> GCP <i/> Azure <i/> Oracle Cloud <i/> Kubernetes <i/> IaC <i/> CI/CD <i/> Observability</section>
  </main><Footer/></>;
}
function Service({icon,title,copy}:{icon:React.ReactNode;title:string;copy:string}) { return <article className="service-card"><span className="service-icon">{icon}</span><h3>{title}</h3><p>{copy}</p><button onClick={() => navigate('services')}>Learn more <ArrowUpRight size={15}/></button></article> }
const services = [{num:'01',title:'Cloud architecture & AWS engineering',copy:'AWS foundations designed around your workloads: landing zones, networking, IAM, compute, data, security guardrails, resilience and cost-aware service choices.',tags:['AWS','Well-Architected','IAM','Networking','Resilience']},{num:'02',title:'Kubernetes platforms',copy:'Design and delivery for EKS, GKE, AKS and self-managed Kubernetes: cluster strategy, workload deployment, ingress, identity, upgrades and day-two operations.',tags:['Kubernetes','EKS / GKE / AKS','Helm','GitOps']},{num:'03',title:'Terraform & infrastructure as code',copy:'Reusable modules, remote state, environment patterns, policy checks and reviewable delivery pipelines that keep infrastructure repeatable.',tags:['Terraform','OpenTofu','Modules','CI/CD']},{num:'04',title:'Observability & reliability',copy:'Instrument services and platforms with useful metrics, logs and traces; build dashboards, alerts, SLOs and incident-ready runbooks.',tags:['OpenTelemetry','Prometheus','Grafana','Loki / Tempo']},{num:'05',title:'CI/CD & developer experience',copy:'Build safer paths to production with automated tests, artifact management, GitOps, progressive delivery and practical developer workflows.',tags:['GitHub Actions','Argo CD','GitLab CI','Release engineering']},{num:'06',title:'Cloud security & cost optimization',copy:'Review identity, network boundaries, secrets, backups, logging and cloud spend; prioritize fixes that reduce risk without slowing delivery.',tags:['Threat modeling','Guardrails','FinOps','Recovery']},{num:'07',title:'Rust engineering',copy:'Production APIs and internal tools in Rust: fast, dependable and designed for teams that care about performance and operational clarity.',tags:['Rust','Axum','Tokio','DynamoDB']}];
function Services() { return <><main><PageIntro eyebrow="Capabilities" title={<>Engineering for<br/><em>systems that ship.</em></>} copy="From cloud foundations to production operations, get focused help across AWS, Kubernetes, Terraform, cloud cost optimization, observability, delivery and Rust engineering."/><section className="service-list wrap">{services.map(s=><article key={s.num}><span className="service-num">{s.num}</span><div><h2>{s.title}</h2><p>{s.copy}</p><div className="tags">{s.tags.map(t=><span key={t}>{t}</span>)}</div></div><ArrowUpRight className="service-arrow"/></article>)}</section><section className="social-panel wrap"><div><div className="eyebrow">Stay connected</div><h2>Build in the open.</h2><p>Follow my engineering work and connect with me across the developer community.</p></div><div className="social-links"><a href="https://www.linkedin.com/in/harishsudalaimani/" target="_blank" rel="noreferrer">LinkedIn <ArrowUpRight size={15}/></a><a href="https://x.com/Harish_8_" target="_blank" rel="noreferrer">X / Twitter <ArrowUpRight size={15}/></a><a href="https://discordapp.com/users/1341650829115002911" target="_blank" rel="noreferrer">Discord <ArrowUpRight size={15}/></a><a href="https://github.com/harishSudalaimani" target="_blank" rel="noreferrer">GitHub <ArrowUpRight size={15}/></a></div></section><section className="principles wrap"><div className="eyebrow">Our operating principles</div><div className="principle-grid"><div><strong>01</strong><h3>Earn complexity.</h3><p>Every service has a job to do. If it doesn’t move the product forward, it doesn’t belong.</p></div><div><strong>02</strong><h3>Own the seams.</h3><p>The most important architecture decisions happen between systems, teams and handoffs.</p></div><div><strong>03</strong><h3>Leave it clearer.</h3><p>Your team should understand, operate and confidently change what we build together.</p></div></div></section></main><Footer/></> }
function PageIntro({eyebrow,title,copy}:{eyebrow:string;title:React.ReactNode;copy:string}) { return <section className="page-intro wrap"><div className="eyebrow"><i/> {eyebrow}</div><h1>{title}</h1><p>{copy}</p></section> }
function Work() { return <><main><PageIntro eyebrow="Real-world examples" title={<>Architecture for<br/><em>the messy middle.</em></>} copy="Illustrative patterns for common production challenges—showing the services, trade-offs and operating practices that make a system work."/><section className="cases wrap"><Case tone="olive" label="Example 01 · SaaS platform" title="A secure foundation for a growing product" copy="Serve the web app through CloudFront and WAF, run containerized APIs on ECS or EKS and keep state in fit-for-purpose managed databases. Terraform-managed networking, least-privilege IAM, encrypted secrets, backups and traces make the foundation safer to evolve." stat="AWS" statLabel="edge · compute · data"/><Case tone="teal" label="Example 02 · commerce" title="Event-driven ordering that handles peaks" copy="Separate checkout from downstream fulfillment with a durable queue and event bus. Keep transactional order data authoritative, use a cache and read model for busy catalog paths and make consumers idempotent with retries and dead-letter handling." stat="Events" statLabel="queues · retries · read models"/><Case tone="olive" label="Example 03 · platform team" title="A Kubernetes platform teams can operate" copy="Standardize clusters, namespaces, ingress, workload identity, secrets, policy and autoscaling. Deliver through Terraform and GitOps, then use OpenTelemetry with Prometheus, Grafana, Loki and Tempo to connect service health to deployment and incident workflows." stat="K8s" statLabel="platform · GitOps · telemetry"/></section><section className="quote-section example-disclaimer"><div className="eyebrow">A note on these examples</div><p>These are representative architecture patterns, not claims about named client engagements or measured customer outcomes. Every recommendation should be shaped around your actual workload and constraints.</p><a className="button" href={MEETING_URL} target="_blank" rel="noreferrer">Discuss your architecture <ArrowUpRight size={16}/></a></section></main><Footer/></> }
function Case({tone,label,title,copy,stat,statLabel}:{tone:string;label:string;title:string;copy:string;stat:string;statLabel:string}) { return <article className={'case '+tone}><div className="case-art"><div className="case-grid"/><span className="case-mark">✦</span><small>{label}</small></div><div className="case-copy"><div><h2>{title}</h2><p>{copy}</p><a href={MEETING_URL} target="_blank" rel="noreferrer">Discuss this architecture <ArrowUpRight size={15}/></a></div><div className="case-stat"><strong>{stat}</strong><span>{statLabel}</span></div></div></article> }
